CREATE OR REPLACE FUNCTION "public"."offline_voucher_state"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_uid     uuid := auth.uid();
  v_enabled boolean;
  v_lines   jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'code', 'UNAUTHORIZED');
  END IF;

  SELECT COALESCE(NULLIF(config_value, ''), 'false')::boolean INTO v_enabled
    FROM public.system_configs WHERE config_key = 'OFFLINE_VOUCHER_ENABLED';

  SELECT COALESCE(jsonb_agg(x ORDER BY x ->> 'phone_number'), '[]'::jsonb)
    INTO v_lines
    FROM (
      SELECT jsonb_build_object(
               'sim_line_id',  sl.id,
               'phone_number', sl.phone_number,
               'nickname',     sl.nickname,
               'carrier_id',   sl.carrier_id,
               'carrier_name', c.name,
               'plan_type',    sl.plan_type,
               'entitled',     (sl.plan_type IN ('premium', 'standard') OR public.has_paid_premium_entitlement(sl.id)),
               'is_premium',   (sl.plan_type = 'premium' OR public.has_paid_premium_entitlement(sl.id)),
               'grant', CASE WHEN g.id IS NULL THEN NULL ELSE jsonb_build_object(
                          'id',              g.id,
                          'status',          g.status,
                          'amount_due_usd',  g.amount_due_usd,
                          'face_value_usd',  s.face_value_usd,
                          'revealed_at',     g.revealed_at,
                          'provisioned_at',  g.provisioned_at,
                          'expires_at',      g.expires_at
                        ) END,
               'request', CASE WHEN r.id IS NULL THEN NULL ELSE jsonb_build_object(
                            'due_at', r.due_at,
                            'reason', r.reason
                          ) END,
               'stock_available', (
                 SELECT count(*) > 0
                   FROM public.offline_voucher_stock st
                  WHERE st.carrier_id = sl.carrier_id
                    AND st.status = 'available'
                    AND (st.expires_at IS NULL OR st.expires_at > now() + interval '7 days')
               ),
               'carrier_redemption', CASE WHEN cr.carrier_id IS NULL THEN NULL ELSE jsonb_build_object(
                 'instructions', cr.instructions,
                 'redeem_ussd_template', CASE WHEN cr.verified_at IS NOT NULL THEN cr.redeem_ussd_template END
               ) END
             ) AS x
        FROM public.sim_lines sl
        LEFT JOIN public.carriers c ON c.id = sl.carrier_id
        LEFT JOIN public.offline_voucher_grants g
               ON g.sim_line_id = sl.id
              AND g.status IN ('provisioned', 'revealed')
        LEFT JOIN public.offline_voucher_stock s ON s.id = g.stock_id
        LEFT JOIN public.offline_voucher_requests r
               ON r.sim_line_id = sl.id
              AND r.status IN ('pending', 'processing')
        LEFT JOIN public.carrier_voucher_redemption cr ON cr.carrier_id = sl.carrier_id
       WHERE sl.user_id = v_uid
    ) rows;

  RETURN jsonb_build_object(
    'success', true,
    'enabled', COALESCE(v_enabled, false),
    'lines', v_lines
  );
END;
$$;

REVOKE ALL ON FUNCTION public.offline_voucher_state() FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION public.offline_voucher_state() TO authenticated;

GRANT EXECUTE ON FUNCTION public.offline_voucher_state() TO service_role;

CREATE OR REPLACE FUNCTION "public"."admin_list_voucher_requests"("p_status" "text" DEFAULT 'open'::"text", "p_limit" integer DEFAULT 200) RETURNS TABLE("id" "uuid", "user_id" "uuid", "user_email" "text", "sim_line_id" "uuid", "phone_number" "text", "carrier_id" "uuid", "carrier_name" "text", "country_name" "text", "reason" "text", "status" "text", "opened_at" timestamp with time zone, "due_at" timestamp with time zone, "is_overdue" boolean, "hours_remaining" numeric, "available_stock" bigint, "note" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  PERFORM public.assert_admin();

  RETURN QUERY
  SELECT r.id, r.user_id, p.email, r.sim_line_id, sl.phone_number,
         r.carrier_id, c.name, co.name, r.reason, r.status,
         r.opened_at, r.due_at,
         (r.status = 'open' AND r.due_at < now()),
         round(EXTRACT(EPOCH FROM (r.due_at - now())) / 3600.0, 1),
         (SELECT count(*) FROM offline_voucher_stock st
           WHERE st.carrier_id = r.carrier_id AND st.status = 'available'),
         r.note
    FROM offline_voucher_requests r
    JOIN sim_lines sl ON sl.id = r.sim_line_id
    JOIN carriers c ON c.id = r.carrier_id
    JOIN countries co ON co.id = c.country_id
    LEFT JOIN profiles p ON p.id = r.user_id
   WHERE (p_status IS NULL OR r.status = p_status)
   ORDER BY r.due_at ASC
   LIMIT GREATEST(1, LEAST(COALESCE(p_limit, 200), 1000));
END;
$$;

REVOKE ALL ON FUNCTION public.admin_list_voucher_requests(text, integer) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION public.admin_list_voucher_requests(text, integer) TO authenticated;

GRANT EXECUTE ON FUNCTION public.admin_list_voucher_requests(text, integer) TO service_role;

